using Htt.Infrastructure;
using Htt.SharedKernel;
using Htt.Host.Api.MasterData;
using NpgsqlTypes;
using static Htt.Host.Api.MasterData.MasterDataSupport;
using static Htt.Host.Api.Sales.SalesSupport;
namespace Htt.Host.Api.Accounting;
public sealed record GeneralBankLine(Guid AccountId,string Description,decimal Net,decimal Tax,Guid TaxCodeId,string BasClass,string CashFlowCategory="OPERATING",decimal? RecoverableTax=null,decimal InputTaxedPercent=0);
public sealed record GeneralBankInput(string Kind,Guid BankAccountId,DateOnly OccurredOn,string Reference,string Reason,bool NoPriorPostingConfirmed,IReadOnlyList<GeneralBankLine>? Lines,string? TaxInvoiceReference=null,DateOnly? TaxInvoiceHeldOn=null);
public sealed record BankClassificationInput(string Reference,string Reason,bool NoPriorPostingConfirmed,IReadOnlyList<GeneralBankLine>? Lines,string? TaxInvoiceReference=null,DateOnly? TaxInvoiceHeldOn=null);
public sealed record BankTransferInput(Guid FromBankAccountId,Guid ToBankAccountId,DateOnly TransferredOn,decimal Amount,string Reference,string Reason,string? BoundaryActivity=null);
public sealed record BankTransactionReversalInput(string Reference,string Reason);
internal static class GeneralBankingEndpoints
{
 private static readonly string[] ReadCaps=["accounting.bank_transactions.read","accounting.banks.read","accounting.ledger.read","accounting.gst.read","purchase.input_gst.read"];
 private static void WriteAccess(HttpContext h,string cap,bool classify=false){foreach(var p in new[]{cap,"accounting.banks.use","accounting.cash_flow.classify","accounting.reports.read"}.Concat(classify?["accounting.bank_transactions.post","accounting.bank_statements.read","accounting.bank_statements.match"]:Array.Empty<string>()))if(!Access(h).Has(p))throw new BusinessException("permission_denied","General banking command and related cash/report permissions required.",403);}
 private static long Version(HttpContext h){if(!long.TryParse(h.Request.Headers.IfMatch.ToString().Trim('"'),out var v)||v<1)throw new BusinessException("version_required","Current If-Match required.",428);return v;}
 private static string Text(string x,string field,int max)=>Check.Text(x,field,max);
 private static GeneralBankLine[] Lines(IReadOnlyList<GeneralBankLine>? input)
 {var rows=input?.ToArray()??[];Check.That(rows.Length is>=1 and<=50&&rows.All(x=>x is not null),"lines","Supply 1..50 settled lines.");return rows.Select(x=>{Check.That(x.AccountId!=Guid.Empty&&x.TaxCodeId!=Guid.Empty,"lines","Company account and tax code IDs required.");Check.Amount(x.Net,"net",2);Check.Amount(x.Tax,"tax",2);Check.That(x.Net>0&&x.Tax>=0,"lines","Positive net and nonnegative tax required.");if(x.RecoverableTax is{} rec){Check.Amount(rec,"recoverableTax",2);Check.That(rec>=0&&rec<=x.Tax,"recoverableTax","Claim cannot exceed tax.");}Check.Amount(x.InputTaxedPercent,"inputTaxedPercent",4);Check.That(x.InputTaxedPercent>=0&&x.InputTaxedPercent<=100,"inputTaxedPercent","Use 0..100.");Check.OneOf(x.BasClass,"basClass","TAXABLE","EXPORT","OTHER_GST_FREE","INPUT_TAXED","CAPITAL","NON_CAPITAL","EXCLUDED");Check.OneOf(x.CashFlowCategory,"cashFlowCategory","OPERATING","INVESTING","FINANCING");return x with{Description=Text(x.Description,"description",500)};}).ToArray();}
 private const string DetailSql="""
 SELECT jsonb_build_object('transaction',jsonb_build_object('id',h.id,'companyId',h.company_id,'kind',h.kind,'bankAccountId',h.bank_account_id,'counterBankAccountId',h.counter_bank_account_id,'occurredOn',h.occurred_on,'reference',h.reference,'reason',h.reason,'gstBasis',h.gst_basis,'gstRegistered',h.gst_registered,'gross',h.gross::text,'journalEntryId',h.journal_entry_id,'statementLineId',h.statement_line_id,'createdAt',h.created_at,'createdBy',h.created_by,'number',d.number,'version',d.version,'state',CASE WHEN EXISTS(SELECT 1 FROM accounting.bank_transaction_reversals v WHERE v.company_id=h.company_id AND v.original_id=h.id)THEN'REVERSED'ELSE'POSTED'END),'lines',coalesce((SELECT jsonb_agg(jsonb_build_object('id',l.id,'lineNo',l.line_no,'accountId',l.account_id,'description',l.description,'net',l.net::text,'tax',l.tax::text,'recoverableTax',l.recoverable_tax::text,'taxCodeId',l.tax_code_id,'taxCategory',l.tax_category,'taxRate',l.tax_rate::text,'taxAccountId',l.tax_account_id,'basClass',l.bas_class,'inputTaxedPercent',l.input_taxed_percent::text,'cashFlowCategory',l.cash_flow_category,'snapshot',l.snapshot)ORDER BY line_no)FROM accounting.bank_transaction_lines l WHERE l.company_id=h.company_id AND l.transaction_id=h.id),'[]'::jsonb),'reversal',(SELECT jsonb_build_object('id',v.id,'originalId',v.original_id,'reference',v.reference,'reason',v.reason,'journalEntryId',v.journal_entry_id,'createdAt',v.created_at,'createdBy',v.created_by)FROM accounting.bank_transaction_reversals v WHERE v.company_id=h.company_id AND v.original_id=h.id),'activeMatches',coalesce((SELECT jsonb_agg(DISTINCT m.id)FROM accounting.active_bank_matches m JOIN accounting.bank_match_allocations a ON a.company_id=m.company_id AND a.match_id=m.id JOIN accounting.journal_lines l ON l.company_id=a.company_id AND l.id=a.journal_line_id WHERE l.company_id=h.company_id AND l.journal_entry_id=h.journal_entry_id),'[]'::jsonb))::text AS result FROM accounting.bank_transactions h JOIN platform.documents d ON d.company_id=h.company_id AND d.id=h.id WHERE h.company_id=@company AND h.id=@id
 """;
 private static async Task<System.Text.Json.JsonElement> Detail(CompanySession s,Guid id,CancellationToken ct){using var json=System.Text.Json.JsonDocument.Parse((string)(await One(s,DetailSql,ct,new DbArg("id",id)))["result"]!);return json.RootElement.Clone();}
 public static void Map(RouteGroupBuilder g)
 {
  g=g.MapGroup("").AddEndpointFilter(async(context,next)=>{foreach(var cap in ReadCaps)if(!Access(context.HttpContext).Has(cap))throw new BusinessException("permission_denied","General banking, directory, ledger and GST read permissions required.",403);return await next(context);});
  g.MapGet("/bank-transactions/{id:guid}",async(Guid id,CompanySession s,CancellationToken ct)=>Results.Ok(await Detail(s,id,ct))).WithMetadata(new Permission("accounting.bank_transactions.read"));
  g.MapGet("/bank-transactions",async(Guid? bankAccountId,int? page,int? pageSize,CompanySession s,CancellationToken ct)=>{var(offset,size)=Page(page,pageSize);return Results.Ok(new{items=(await Read(s,"SELECT h.*,d.number,d.version,EXISTS(SELECT 1 FROM accounting.bank_transaction_reversals v WHERE v.company_id=h.company_id AND v.original_id=h.id)AS reversed FROM accounting.bank_transactions h JOIN platform.documents d ON d.company_id=h.company_id AND d.id=h.id WHERE h.company_id=@company AND(@bank IS NULL OR h.bank_account_id=@bank OR h.counter_bank_account_id=@bank)ORDER BY h.occurred_on DESC,h.id LIMIT @size OFFSET @offset",ct,new DbArg("bank",bankAccountId,NpgsqlDbType.Uuid),new DbArg("size",size),new DbArg("offset",offset))).Select(PublicRow),page=page??1,pageSize=size});}).WithMetadata(new Permission("accounting.bank_transactions.read"));
  g.MapPost("/bank-transactions",Post).WithMetadata(new Permission("accounting.bank_transactions.post"));
  g.MapPost("/bank-transfers",Transfer).WithMetadata(new Permission("accounting.bank_transactions.transfer"));
  g.MapPost("/bank-statement-lines/{id:guid}/classify",Classify).WithMetadata(new Permission("accounting.bank_transactions.classify"));
  g.MapPost("/bank-transactions/{id:guid}/reverse",Reverse).WithMetadata(new Permission("accounting.bank_transactions.reverse"));
 }
 private static async Task<Guid> PostSql(CompanySession s,GeneralBankInput x,CancellationToken ct,Guid? statement=null,long? version=null)
 =>(Guid)(await One(s,"SELECT accounting.post_general_banking(@kind,@bank,NULL,@date,@reference,@reason,@lines,NULL,NULL,@confirm,@evidence,@held,@statement,@version)AS id",ct,new DbArg("kind",x.Kind),new DbArg("bank",x.BankAccountId),new DbArg("date",x.OccurredOn),new DbArg("reference",x.Reference),new DbArg("reason",x.Reason),new DbArg("lines",Json(x.Lines!),NpgsqlDbType.Jsonb),new DbArg("confirm",x.NoPriorPostingConfirmed),new DbArg("evidence",x.TaxInvoiceReference,NpgsqlDbType.Text),new DbArg("held",x.TaxInvoiceHeldOn,NpgsqlDbType.Date),new DbArg("statement",statement,NpgsqlDbType.Uuid),new DbArg("version",version,NpgsqlDbType.Bigint)))["id"]!;
 private static GeneralBankInput Validate(GeneralBankInput x)
 {Check.OneOf(x.Kind,"kind","RECEIVE","PAY");Check.That(x.OccurredOn.Year>=2&&x.BankAccountId!=Guid.Empty,"date","Valid cash date and bank required.");Check.That(x.NoPriorPostingConfirmed,"noPriorPostingConfirmed","Confirm there is no prior invoice, tax claim or ledger posting; otherwise use existing invoice/settlement flows.");return x with{Reference=Text(x.Reference,"reference",200),Reason=Text(x.Reason,"reason",2000),Lines=Lines(x.Lines),TaxInvoiceReference=Check.Optional(x.TaxInvoiceReference,"taxInvoiceReference",500)};}
 private static async Task<IResult> Post(GeneralBankInput input,HttpContext h,CompanySession s,Idempotency idem,CancellationToken ct)
 {WriteAccess(h,"accounting.bank_transactions.post");var x=Validate(input);var response=await idem.ExecuteAsync("POST /bank-transactions",h.Request.Headers["Idempotency-Key"].ToString(),Json(x),async()=>{var id=await PostSql(s,x,ct);await Sql.AuditAsync(s,"accounting.general_bank_posted","bank_transaction",id,h.TraceIdentifier,ct);return ApiJson.Stored(await Detail(s,id,ct),201);},ct);return ApiJson.Result(response);}
 private static async Task<IResult> Transfer(BankTransferInput input,HttpContext h,CompanySession s,Idempotency idem,CancellationToken ct)
 {WriteAccess(h,"accounting.bank_transactions.transfer");Check.That(input.FromBankAccountId!=Guid.Empty&&input.ToBankAccountId!=Guid.Empty&&input.FromBankAccountId!=input.ToBankAccountId&&input.TransferredOn.Year>=2,"banks","Distinct company banks and date required.");Check.Amount(input.Amount,"amount",2);Check.That(input.Amount>0,"amount","Positive AUD cents required.");if(input.BoundaryActivity is{} category)Check.OneOf(category,"boundaryActivity","OPERATING","INVESTING","FINANCING");var x=input with{Reference=Text(input.Reference,"reference",200),Reason=Text(input.Reason,"reason",2000)};var response=await idem.ExecuteAsync("POST /bank-transfers",h.Request.Headers["Idempotency-Key"].ToString(),Json(x),async()=>{var id=(Guid)(await One(s,"SELECT accounting.post_general_banking('TRANSFER',@bank,@other,@date,@reference,@reason,'[]',@amount,@category,false,NULL,NULL)AS id",ct,new DbArg("bank",x.FromBankAccountId),new DbArg("other",x.ToBankAccountId),new DbArg("date",x.TransferredOn),new DbArg("reference",x.Reference),new DbArg("reason",x.Reason),new DbArg("amount",x.Amount),new DbArg("category",x.BoundaryActivity,NpgsqlDbType.Text)))["id"]!;await Sql.AuditAsync(s,"accounting.bank_transferred","bank_transaction",id,h.TraceIdentifier,ct);return ApiJson.Stored(await Detail(s,id,ct),201);},ct);return ApiJson.Result(response);}
 private static async Task<IResult> Classify(Guid id,BankClassificationInput input,HttpContext h,CompanySession s,Idempotency idem,CancellationToken ct)
 {WriteAccess(h,"accounting.bank_transactions.classify",true);var row=await One(s,"SELECT bank_account_id,transaction_date,amount FROM accounting.bank_statement_lines WHERE company_id=@company AND id=@id",ct,new DbArg("id",id));var version=Version(h);var x=Validate(new((decimal)row["amount"]!>0?"RECEIVE":"PAY",(Guid)row["bank_account_id"]!,row["transaction_date"] is DateOnly day?day:DateOnly.FromDateTime((DateTime)row["transaction_date"]!),input.Reference,input.Reason,input.NoPriorPostingConfirmed,input.Lines,input.TaxInvoiceReference,input.TaxInvoiceHeldOn));var response=await idem.ExecuteAsync($"POST /bank-statement-lines/{id}/classify",h.Request.Headers["Idempotency-Key"].ToString(),Json(new{id,version,x}),async()=>{var doc=await PostSql(s,x,ct,id,version);await Sql.AuditAsync(s,"accounting.bank_line_classified","bank_transaction",doc,h.TraceIdentifier,ct,new{statementLineId=id});return ApiJson.Stored(await Detail(s,doc,ct),201);},ct);return ApiJson.Result(response);}
 private static async Task<IResult> Reverse(Guid id,BankTransactionReversalInput input,HttpContext h,CompanySession s,Idempotency idem,CancellationToken ct)
 {WriteAccess(h,"accounting.bank_transactions.reverse");await Detail(s,id,ct);var version=Version(h);var x=input with{Reference=Text(input.Reference,"reference",200),Reason=Text(input.Reason,"reason",2000)};var response=await idem.ExecuteAsync($"POST /bank-transactions/{id}/reverse",h.Request.Headers["Idempotency-Key"].ToString(),Json(new{id,version,x}),async()=>{var reversal=(Guid)(await One(s,"SELECT accounting.reverse_general_banking(@id,@version,@ref,@reason)AS id",ct,new DbArg("id",id),new DbArg("version",version),new DbArg("ref",x.Reference),new DbArg("reason",x.Reason)))["id"]!;await Sql.AuditAsync(s,"accounting.general_bank_reversed","bank_transaction",id,h.TraceIdentifier,ct,new{reversalId=reversal});return ApiJson.Stored(await Detail(s,id,ct),200);},ct);return ApiJson.Result(response);}
}
